// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import "./libraries/ATMActions.sol";

abstract contract Initializable {
    bool private _initialized;
    bool private _initializing;

    modifier initializer() {
        require(
            _initializing || !_initialized,
            "Initializable: contract is already initialized"
        );
        bool isTopLevelCall = !_initializing;
        if (isTopLevelCall) {
            _initializing = true;
            _initialized = true;
        }
        _;
        if (isTopLevelCall) {
            _initializing = false;
        }
    }

    modifier onlyInitializing() {
        require(_initializing, "Initializable: contract is not initializing");
        _;
    }

    function _disableInitializers() internal {
        require(!_initializing, "Initializable: cannot disable during initialization");
        _initialized = true;
    }
}

contract Ownable is Initializable {
    address private _owner;
    address private _pendingOwner;

    event OwnershipTransferInitiated(address indexed currentOwner, address indexed pendingOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    function __Ownable_init_unchained() internal onlyInitializing {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function pendingOwner() public view returns (address) {
        return _pendingOwner;
    }

    modifier onlyOwner() {
        _checkOwner();
        _;
    }

    function _checkOwner() internal view {
        require(msg.sender == _owner, "Ownable: caller is not the owner");
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: zero address");
        _pendingOwner = newOwner;
        emit OwnershipTransferInitiated(_owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == _pendingOwner, "Ownable: not pending owner");
        emit OwnershipTransferred(_owner, _pendingOwner);
        _owner = _pendingOwner;
        _pendingOwner = address(0);
    }
}

/// @title ATMAccessControl v1.1.0
/// @notice Core of the access-control system: wallet status (blacklisted / frozen / protected),
///         safe-wallet links, per-type rules and connection checks, and all admin / operator
///         actions. User approval dao live in a separate, pausable ACL DAO contract that can only
///         change state through the narrow `dao*` hooks below; every hook re-checks invariants.
/// @dev Invariants kept by every write path:
///      - no chains: a PROTECTED wallet is never a safe wallet, and a safe wallet never becomes
///        PROTECTED, so a wallet's status depends on at most one safe wallet;
///      - a safe wallet that is frozen / blacklisted / revoked never receives payouts.
contract ATMAccessControl is Initializable, Ownable {

    mapping(address => bool) public operators;

    mapping(address => bool) private _blacklisted;

    mapping(address => bool) private _frozen;

    mapping(address => address) private _safeWallet;

    /// @dev Deprecated: was set once and never cleared, so it only meant "was ever a safe wallet".
    ///      Kept to preserve the storage layout; no longer written or read. Use isSafeWallet().
    mapping(address => bool) private _isSafeWalletDeprecated;

    mapping(address => uint256) private _activeSafeWalletCount;

    mapping(address => bool) private _safeWalletRevoked;

    uint256 public proposalThreshold;

    uint256 public constant MAX_PROPOSAL_THRESHOLD = 100;

    uint256 public constant MAX_BATCH_SIZE = 500;

    /// @dev AssignType / RemoveType appended in v1.1.0 (custom types; type id in proposalTypeId)
    enum ProposalType { SetSafeWallet, UnFreeze, UnBlacklist, MoveToFrozen, AssignType, RemoveType }

    struct Proposal {
        ProposalType proposalType;
        address[] addrs;
        address[] aux;
        uint256 approvalCount;
        uint256 snapshotThreshold;
        bool executed;
        bool cancelled;
        address proposer;
    }

    uint256 public proposalCount;
    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) private _proposalApprovals;

    // ---------------------------------------------------------------------
    // v1.1.0. Appended after all v1.0.0 storage; do not reorder.
    // ---------------------------------------------------------------------

    /// @dev Built-in types. 1 and 2 read the existing _blacklisted / _frozen state (no copy).
    uint256 public constant TYPE_BLACKLISTED = 1;
    uint256 public constant TYPE_FROZEN = 2;
    uint256 public constant TYPE_PROTECTED = 3;
    /// @dev id 4 is retired (was VERIFIER; verifiers are now a custom type chosen in the ACL DAO)
    uint256 public constant FIRST_CUSTOM_TYPE = 5;
    /// @dev bounds the isAllowed loop
    uint256 public constant MAX_TYPES_PER_USER = 8;

    /// @dev rule values: 0 = not set, 1 = allow, 2 = block
    uint8 internal constant RULE_UNSET = 0;
    uint8 internal constant RULE_ALLOW = 1;
    uint8 internal constant RULE_BLOCK = 2;

    /// @dev canCreateConnection reasons: 0 ok, 1 creator rule, 2 userB rule, 3 lock days, 4 amount,
    ///      5 percentA, 6 time range
    uint8 internal constant CONN_OK = 0;
    uint8 internal constant DENY_CREATOR = 1;
    uint8 internal constant DENY_USER_B = 2;
    uint8 internal constant DENY_LOCK_DAYS = 3;
    uint8 internal constant DENY_AMOUNT = 4;
    uint8 internal constant DENY_PERCENT = 5;
    uint8 internal constant DENY_TIME = 6;

    /// @dev same values as ATMActions (exposed for off-chain tools)
    bytes32 public constant CREATE_CONNECTION = keccak256("CREATE_CONNECTION");
    bytes32 public constant JOIN_CONNECTION = keccak256("JOIN_CONNECTION");
    bytes32 public constant JOIN_FULLY_PAID = keccak256("JOIN_FULLY_PAID");

    struct TypeInfo {
        string name;
        bool exists;
        bool disabled; // disabled types block nothing and have no limits
        bool defaultBlocked; // actions without a rule are blocked
        bool daoAllowed; // the ACL DAO (verifier vote) may add / remove wallets in this custom type
    }

    /// @dev 0 = no limit for every field. Amount applies to the connection's totalPlan.
    struct ConnectionLimits {
        uint32 minLockDays;
        uint32 maxLockDays;
        uint64 startTime;
        uint64 endTime;
        uint8 minPercentA;
        uint8 maxPercentA;
        bool set;
        uint128 minAmount;
        uint128 maxAmount;
    }

    uint256 public lastTypeId;
    mapping(uint256 => TypeInfo) private _types;
    /// @notice keccak256(name) => type id (0 = unused). Built-in names are reserved.
    mapping(bytes32 => uint256) public typeIdByName;
    /// @dev typeId => action => rule
    mapping(uint256 => mapping(bytes32 => uint8)) private _rules;
    /// @dev typeId => action => token => rule (overrides the general rule for that token)
    mapping(uint256 => mapping(bytes32 => mapping(address => uint8))) private _tokenRules;
    /// @dev types held through assignType / protection (built-ins 1-2 are not stored here)
    mapping(address => uint256[]) private _userTypes;
    /// @dev user => typeId => index in _userTypes + 1 (0 = not held)
    mapping(address => mapping(uint256 => uint256)) private _userTypeIndex;
    /// @dev bumped each time a wallet that is someone's safe wallet is frozen / blacklisted
    mapping(address => uint256) private _restrictCount;
    /// @dev wallet => _restrictCount of its safe wallet when its types were granted / last valid.
    ///      Mismatch = the safe wallet was restricted since: custom types are expired.
    mapping(address => uint256) private _typesEpoch;
    mapping(uint256 => ConnectionLimits) private _limits;
    mapping(uint256 => mapping(address => ConnectionLimits)) private _tokenLimits;
    /// @notice The only contract allowed to call the dao* hooks.
    address public dao;
    /// @notice When true, every dao* hook reverts. Reads, payouts and freeze are never paused.
    bool public daoPaused;
    /// @notice Custom type of an AssignType / RemoveType proposal (0 for other proposals).
    mapping(uint256 => uint256) public proposalTypeId;

    // v1.1.0 errors (v1.0.0 functions keep their revert strings)
    error AccountIsSafeWallet();
    error AccountRestricted();
    error BadLimits();
    error BadRule();
    error EmptyName();
    error DaoPaused();
    error LengthMismatch();
    error NotAssignable();
    error NotDao();
    error NotFrozen();
    error NotOperator();
    error NotProtected();
    error ReservedName();
    error SafeWalletUnusable();
    error TooManyTypes();
    error TypeExists();
    error UnknownType();
    error ZeroAction();

    event OperatorSet(address indexed operator, bool allowed);
    event Blacklisted(address indexed account);
    event UnBlacklisted(address indexed account);
    event Frozen(address indexed account);
    event UnFrozen(address indexed account);
    event SafeWalletSet(address indexed frozenAddress, address indexed safeWallet);
    event SafeWalletRestricted(address indexed safeWallet);
    event SafeWalletRevocationCleared(address indexed safeWallet);
    event SafeWalletRequired(address indexed account);
    event ProposalThresholdSet(uint256 threshold);
    event ProposalCreated(uint256 indexed proposalId, ProposalType indexed proposalType, address indexed proposer, uint256 batchSize);
    event ProposalApproved(uint256 indexed proposalId, address indexed approver, uint256 approvals, uint256 threshold);
    event ProposalExecuted(uint256 indexed proposalId, ProposalType indexed proposalType);
    event ProposalRejected(uint256 indexed proposalId, address indexed rejector);
    event ProposalAddressSkipped(uint256 indexed proposalId, address indexed addr);
    event TypeCreated(uint256 indexed typeId, string name);
    event TypeDisabledSet(uint256 indexed typeId, bool disabled);
    event TypeDefaultBlockedSet(uint256 indexed typeId, bool defaultBlocked);
    event TypeDaoAllowedSet(uint256 indexed typeId, bool allowed);
    event TypeRuleSet(uint256 indexed typeId, bytes32 indexed action, uint8 rule);
    event TypeTokenRuleSet(uint256 indexed typeId, bytes32 indexed action, address indexed token, uint8 rule);
    event ConnectionLimitsSet(uint256 indexed typeId, address indexed token, bool tokenSpecific);
    event TypeAssigned(address indexed account, uint256 indexed typeId);
    event TypeRemoved(address indexed account, uint256 indexed typeId);
    event DependentsRestricted(address indexed safeWallet, uint256 restrictCount);
    event ProtectionGranted(address indexed wallet, address indexed safeWallet);
    event DaoSet(address indexed dao);
    event DaoPausedSet(bool paused, address indexed by);

    modifier onlyOperator() {
        _checkOperator();
        _;
    }

    function _checkOperator() internal view {
        require(operators[msg.sender], "ATMAccessControl: not operator");
    }

    modifier onlyDao() {
        _checkDao();
        _;
    }

    function _checkDao() internal view {
        if (msg.sender != dao || msg.sender == address(0)) revert NotDao();
        if (daoPaused) revert DaoPaused();
    }

    constructor() {
        _disableInitializers();
    }

    function __ATMAccessControl_init() external initializer {
        __Ownable_init_unchained();
        proposalThreshold = 2;
    }

    function setOperator(address _operator, bool _allowed) external onlyOwner {
        _nonZero(_operator);
        operators[_operator] = _allowed;
        emit OperatorSet(_operator, _allowed);
    }

    function setProposalThreshold(uint256 _threshold) external onlyOwner {
        require(_threshold >= 2, "ATMAccessControl: threshold minimum 2");
        require(_threshold <= MAX_PROPOSAL_THRESHOLD, "ATMAccessControl: threshold too high");
        proposalThreshold = _threshold;
        emit ProposalThresholdSet(_threshold);
    }

    function getProposalAddrs(uint256 proposalId) external view returns (address[] memory) {
        return proposals[proposalId].addrs;
    }

    function getProposalAux(uint256 proposalId) external view returns (address[] memory) {
        return proposals[proposalId].aux;
    }

    function hasApproved(uint256 proposalId, address operator) external view returns (bool) {
        return _proposalApprovals[proposalId][operator];
    }

    function blacklist(address[] calldata addrs) external onlyOperator {
        _checkBatch(addrs.length);
        for (uint256 i = 0; i < addrs.length; i++) {
            _nonZero(addrs[i]);
            _applyBlacklist(addrs[i]);
        }
    }

    function unBlacklist(address[] calldata addrs) external onlyOperator {
        _checkAddrs(addrs);
        _createProposal(ProposalType.UnBlacklist, addrs, new address[](0));
    }

    function isBlacklisted(address _addr) public view returns (bool) {
        return _blacklisted[_addr];
    }

    function moveToFrozen(address[] calldata addrs) external onlyOperator {
        _checkBatch(addrs.length);
        for (uint256 i = 0; i < addrs.length; i++) {
            _nonZero(addrs[i]);
            require(isBlacklisted(addrs[i]), "ATMAccessControl: address is not blacklisted");
        }
        _createProposal(ProposalType.MoveToFrozen, addrs, new address[](0));
    }

    /// @notice Freeze yourself. Same effect as an operator `freeze`, also for an active safe wallet:
    ///         its own payouts stop, every wallet it is the safe wallet of is treated as frozen
    ///         (payouts stop, protection and other types no longer apply) until operators unfreeze it.
    function selfFreeze() external {
        address addr = msg.sender;
        require(!isBlacklisted(addr), "ATMAccessControl: address is blacklisted");
        if (_frozen[addr]) return;
        _applyFreeze(addr);
    }

    function freeze(address[] calldata addrs) external onlyOperator {
        _checkBatch(addrs.length);
        for (uint256 i = 0; i < addrs.length; i++) {
            address addr = addrs[i];
            _nonZero(addr);
            if (isBlacklisted(addr) || _frozen[addr]) continue;
            _applyFreeze(addr);
        }
    }

    function unFreeze(address[] calldata addrs) external onlyOperator {
        _checkBatch(addrs.length);
        for (uint256 i = 0; i < addrs.length; i++) {
            _nonZero(addrs[i]);
            require(_frozen[addrs[i]], "ATMAccessControl: address is not frozen");
        }
        _createProposal(ProposalType.UnFreeze, addrs, new address[](0));
    }

    /// @notice True if the wallet is frozen itself, or is PROTECTED and its safe wallet is
    ///         frozen / blacklisted / revoked (it takes the safe wallet's status).
    function isFrozen(address _addr) public view returns (bool) {
        return _frozen[_addr] || _inheritsFrozen(_addr);
    }

    /// @notice Operators set the safe wallet of a FROZEN or PROTECTED wallet (proposal + threshold).
    function setSafeWallet(address[] calldata addrs, address[] calldata safeWallets) external onlyOperator {
        require(addrs.length == safeWallets.length, "ATMAccessControl: length mismatch");
        _checkBatch(addrs.length);
        _validateSafeWalletBatch(addrs, safeWallets);
        _createProposal(ProposalType.SetSafeWallet, addrs, safeWallets);
    }

    function safeWalletOf(address _addr) external view returns (address) {
        return _safeWallet[_addr];
    }

    function isSafeWalletRevoked(address _addr) external view returns (bool) {
        return _safeWalletRevoked[_addr];
    }

    /// @notice True if `_addr` is currently the safe wallet of at least one frozen or protected wallet.
    function isSafeWallet(address _addr) external view returns (bool) {
        return _activeSafeWalletCount[_addr] > 0;
    }

    /// @notice Number of frozen or protected wallets that currently use `_addr` as their safe wallet.
    function activeSafeWalletCount(address _addr) external view returns (uint256) {
        return _activeSafeWalletCount[_addr];
    }

    function approveProposal(uint256 proposalId) external onlyOperator {
        Proposal storage p = _notExecuted(proposalId);
        require(!p.cancelled, "ATMAccessControl: proposal cancelled");
        require(!_proposalApprovals[proposalId][msg.sender], "ATMAccessControl: already approved");

        _proposalApprovals[proposalId][msg.sender] = true;
        uint256 approvals = ++p.approvalCount;

        emit ProposalApproved(proposalId, msg.sender, approvals, p.snapshotThreshold);

        if (approvals >= p.snapshotThreshold) {
            _executeProposal(proposalId);
        }
    }

    function rejectProposal(uint256 proposalId) external {
        Proposal storage p = _notExecuted(proposalId);
        require(!p.cancelled, "ATMAccessControl: already cancelled");
        require(
            msg.sender == p.proposer || msg.sender == owner(),
            "ATMAccessControl: only proposer or owner can reject"
        );
        p.cancelled = true;
        emit ProposalRejected(proposalId, msg.sender);
    }

    /// @notice Where payouts for `_addr` go; address(0) = blocked.
    function redirectTarget(address _addr) public view returns (address) {
        if (_blacklisted[_addr]) return address(0);
        address safe = _safeWallet[_addr];
        if (_frozen[_addr]) {
            if (safe == address(0) || _safeUnusable(safe)) return address(0);
            return safe;
        }
        if (safe != address(0) && isProtected(_addr)) {
            // protected: payouts to the safe wallet; blocked while it is restricted
            return _safeUnusable(safe) ? address(0) : safe;
        }
        return _addr;
    }

    function isRestricted(address _addr) public view returns (bool) {
        return isBlacklisted(_addr) || isFrozen(_addr);
    }

    function _createProposal(
        ProposalType pType,
        address[] memory addrs,
        address[] memory aux
    ) internal {
        uint256 proposalId = proposalCount++;
        Proposal storage p = proposals[proposalId];
        p.proposalType = pType;
        p.addrs = addrs;
        p.aux = aux;
        p.approvalCount = 1;
        p.snapshotThreshold = proposalThreshold;
        p.proposer = msg.sender;
        _proposalApprovals[proposalId][msg.sender] = true;

        emit ProposalCreated(proposalId, pType, msg.sender, addrs.length);
        emit ProposalApproved(proposalId, msg.sender, 1, p.snapshotThreshold);

        if (p.snapshotThreshold <= 1) {
            _executeProposal(proposalId);
        }
    }

    function _executeProposal(uint256 proposalId) internal {
        Proposal storage p = proposals[proposalId];
        p.executed = true;

        if (p.proposalType == ProposalType.UnBlacklist) {
            for (uint256 i = 0; i < p.addrs.length; i++) {
                address addr = p.addrs[i];
                if (!_blacklisted[addr]) {
                    emit ProposalAddressSkipped(proposalId, addr);
                    continue;
                }
                _applyUnBlacklist(addr);
            }

        } else if (p.proposalType == ProposalType.MoveToFrozen) {
            for (uint256 i = 0; i < p.addrs.length; i++) {
                if (!isBlacklisted(p.addrs[i])) {
                    emit ProposalAddressSkipped(proposalId, p.addrs[i]);
                    continue;
                }
                _applyMoveToFrozen(p.addrs[i]);
            }

        } else if (p.proposalType == ProposalType.UnFreeze) {
            for (uint256 i = 0; i < p.addrs.length; i++) {
                address addr = p.addrs[i];
                if (!_frozen[addr]) {
                    emit ProposalAddressSkipped(proposalId, addr);
                    continue;
                }
                _applyUnfreeze(addr);
            }

        } else if (p.proposalType == ProposalType.SetSafeWallet) {
            for (uint256 i = 0; i < p.addrs.length; i++) {
                address addr = p.addrs[i];
                address safeWallet = p.aux[i];
                if (
                    !(_frozen[addr] || isProtected(addr)) ||
                    isRestricted(safeWallet) ||
                    isProtected(safeWallet)
                ) {
                    emit ProposalAddressSkipped(proposalId, addr);
                    continue;
                }
                _assignSafeWallet(addr, safeWallet);
            }
        } else {
            // AssignType / RemoveType: wallets already in that state, or at MAX_TYPES_PER_USER, are skipped
            uint256 typeId = proposalTypeId[proposalId];
            bool add = p.proposalType == ProposalType.AssignType;
            for (uint256 i = 0; i < p.addrs.length; i++) {
                if (!_setType(p.addrs[i], typeId, add, false)) emit ProposalAddressSkipped(proposalId, p.addrs[i]);
            }
        }

        emit ProposalExecuted(proposalId, p.proposalType);
    }

    function _applyUnBlacklist(address addr) internal {
        if (_blacklisted[addr]) {
            _blacklisted[addr] = false;
            emit UnBlacklisted(addr);
        }
        if (_safeWalletRevoked[addr]) {
            _safeWalletRevoked[addr] = false;
            emit SafeWalletRevocationCleared(addr);
        }
    }

    function _applyBlacklist(address addr) internal {
        if (_frozen[addr]) {
            _applyUnfreeze(addr);
        }
        if (_activeSafeWalletCount[addr] > 0) {
            _safeWalletRevoked[addr] = true;
        }
        if (operators[addr]) {
            operators[addr] = false;
            emit OperatorSet(addr, false);
        }
        if (!_blacklisted[addr]) {
            _blacklisted[addr] = true;
            emit Blacklisted(addr);
            if (_activeSafeWalletCount[addr] > 0) emit SafeWalletRestricted(addr);
        }
        _onRestricted(addr);
    }

    function _applyFreeze(address addr) internal {
        _frozen[addr] = true;
        emit Frozen(addr);
        if (_activeSafeWalletCount[addr] > 0) emit SafeWalletRestricted(addr);
        _onRestricted(addr);
    }

    function _applyUnfreeze(address addr) internal {
        _frozen[addr] = false;
        _clearSafeWalletEntry(addr);
        emit UnFrozen(addr);
    }

    function _applyMoveToFrozen(address addr) internal {
        if (!isBlacklisted(addr)) return;
        _blacklisted[addr] = false;
        _frozen[addr] = true;
        if (_safeWalletRevoked[addr] && _activeSafeWalletCount[addr] == 0) {
            _safeWalletRevoked[addr] = false;
            emit SafeWalletRevocationCleared(addr);
        }
        emit UnBlacklisted(addr);
        emit Frozen(addr);
        if (_safeWallet[addr] == address(0)) {
            emit SafeWalletRequired(addr);
        }
    }

    function _validateSafeWalletBatch(address[] calldata addrs, address[] calldata safeWallets) internal view {
        for (uint256 i = 0; i < addrs.length; i++) {
            _nonZero(addrs[i]);
            require(safeWallets[i] != address(0), "ATMAccessControl: zero safe wallet");
            require(safeWallets[i] != addrs[i], "ATMAccessControl: safe wallet cannot be self");
            require(
                _frozen[addrs[i]] || isProtected(addrs[i]),
                "ATMAccessControl: address is not frozen or protected"
            );
            require(!isRestricted(safeWallets[i]), "ATMAccessControl: safe wallet is itself restricted");
            require(!isProtected(safeWallets[i]), "ATMAccessControl: safe wallet is protected");
        }
    }

    function _assignSafeWallet(address _addr, address _newSafeWallet) internal {
        address old = _safeWallet[_addr];
        if (old == _newSafeWallet) return;
        _syncTypes(_addr);
        if (old != address(0)) {
            _activeSafeWalletCount[old]--;
        }
        _safeWallet[_addr] = _newSafeWallet;
        _activeSafeWalletCount[_newSafeWallet]++;
        _typesEpoch[_addr] = _restrictCount[_newSafeWallet];
        if (_safeWalletRevoked[_newSafeWallet]) {
            _safeWalletRevoked[_newSafeWallet] = false;
            emit SafeWalletRevocationCleared(_newSafeWallet);
        }
        emit SafeWalletSet(_addr, _newSafeWallet);
    }

    function _clearSafeWalletEntry(address _addr) internal {
        address old = _safeWallet[_addr];
        if (old == address(0)) return;
        _syncTypes(_addr);
        _activeSafeWalletCount[old]--;
        _safeWallet[_addr] = address(0);
        _typesEpoch[_addr] = 0; // _restrictCount[address(0)] is always 0
        emit SafeWalletSet(_addr, address(0));
    }

    // ---------------------------------------------------------------------
    // Types (owner)
    // ---------------------------------------------------------------------

    function createType(string calldata name) external onlyOwner returns (uint256 typeId) {
        bytes32 key = _checkName(name);
        typeId = lastTypeId < FIRST_CUSTOM_TYPE ? FIRST_CUSTOM_TYPE : lastTypeId + 1;
        lastTypeId = typeId;
        _types[typeId] = TypeInfo({name: name, exists: true, disabled: false, defaultBlocked: false, daoAllowed: false});
        typeIdByName[key] = typeId;
        emit TypeCreated(typeId, name);
    }

    /// @notice A disabled type blocks nothing and has no limits. Payout routing is not affected.
    function setTypeDisabled(uint256 typeId, bool disabled) external onlyOwner {
        _requireType(typeId);
        _types[typeId].disabled = disabled;
        emit TypeDisabledSet(typeId, disabled);
    }

    /// @notice Deny by default: actions without a rule are blocked for this type.
    function setTypeDefaultBlocked(uint256 typeId, bool defaultBlocked) external onlyOwner {
        _requireType(typeId);
        _types[typeId].defaultBlocked = defaultBlocked;
        emit TypeDefaultBlockedSet(typeId, defaultBlocked);
    }

    /// @notice Lets the ACL DAO (verifier vote) add / remove wallets in this custom type.
    function setTypeDaoAllowed(uint256 typeId, bool allowed) external onlyOwner {
        if (!_isCustomType(typeId)) revert NotAssignable();
        _types[typeId].daoAllowed = allowed;
        emit TypeDaoAllowedSet(typeId, allowed);
    }

    /// @param rules RULE_UNSET (0), RULE_ALLOW (1) or RULE_BLOCK (2) per action
    function setTypeRules(uint256 typeId, bytes32[] calldata actions, uint8[] calldata rules) external onlyOwner {
        _requireType(typeId);
        if (actions.length != rules.length) revert LengthMismatch();
        _checkBatch(actions.length);
        for (uint256 i = 0; i < actions.length; i++) {
            if (actions[i] == bytes32(0)) revert ZeroAction();
            if (rules[i] > RULE_BLOCK) revert BadRule();
            _rules[typeId][actions[i]] = rules[i];
            emit TypeRuleSet(typeId, actions[i], rules[i]);
        }
    }

    /// @notice Token-specific rules override the general rule of `action` for those tokens.
    ///         Native BNB is address(0), as in the Factory token list.
    function setTypeTokenRules(
        uint256 typeId,
        bytes32 action,
        address[] calldata tokens,
        uint8[] calldata rules
    ) external onlyOwner {
        _requireType(typeId);
        if (action == bytes32(0)) revert ZeroAction();
        if (tokens.length != rules.length) revert LengthMismatch();
        _checkBatch(tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            if (rules[i] > RULE_BLOCK) revert BadRule();
            _tokenRules[typeId][action][tokens[i]] = rules[i];
            emit TypeTokenRuleSet(typeId, action, tokens[i], rules[i]);
        }
    }

    /// @notice Connection limits (creator side). tokenSpecific = false: for every token;
    ///         true: only for `token`, overriding the general limits. All-zero clears them.
    function setConnectionLimits(uint256 typeId, address token, bool tokenSpecific, ConnectionLimits calldata limits)
        external
        onlyOwner
    {
        _requireType(typeId);
        ConnectionLimits memory l = _checkedLimits(limits);
        if (tokenSpecific) _tokenLimits[typeId][token] = l;
        else _limits[typeId] = l;
        emit ConnectionLimitsSet(typeId, token, tokenSpecific);
    }

    /// @notice Gives PROTECTED or a custom type. BLACKLISTED / FROZEN use their own flows.
    function assignType(address[] calldata accounts, uint256 typeId) external onlyOwner {
        if (!_isAssignable(typeId)) revert NotAssignable();
        _checkBatch(accounts.length);
        for (uint256 i = 0; i < accounts.length; i++) {
            address a = accounts[i];
            _nonZero(a);
            if (typeId == TYPE_PROTECTED) {
                if (isRestricted(a)) revert AccountRestricted();
                if (_activeSafeWalletCount[a] != 0) revert AccountIsSafeWallet();
            }
            _setType(a, typeId, true, true);
        }
    }

    /// @notice Removing PROTECTED also clears the safe wallet (unless the wallet is frozen,
    ///         where the frozen flow owns it).
    function removeType(address[] calldata accounts, uint256 typeId) external onlyOwner {
        if (!_isAssignable(typeId)) revert NotAssignable();
        _checkBatch(accounts.length);
        for (uint256 i = 0; i < accounts.length; i++) {
            address a = accounts[i];
            if (!_setType(a, typeId, false, false)) continue;
            if (typeId == TYPE_PROTECTED && !_frozen[a]) _clearSafeWalletEntry(a);
        }
    }

    /// @notice Operators add (`add` = true) or remove wallets in a custom type: proposal +
    ///         proposalThreshold approvals, like unFreeze. The owner can still use assignType.
    function proposeTypeChange(address[] calldata accounts, uint256 typeId, bool add) external onlyOperator {
        if (!_isCustomType(typeId)) revert NotAssignable();
        _checkAddrs(accounts);
        proposalTypeId[proposalCount] = typeId; // id _createProposal is about to use
        _createProposal(add ? ProposalType.AssignType : ProposalType.RemoveType, accounts, new address[](0));
    }

    // ---------------------------------------------------------------------
    // Rule checks (views)
    // ---------------------------------------------------------------------

    /// @notice False if any active type of the wallet blocks `action` (strictest wins).
    ///         Wallets with no type and no restriction are always allowed.
    function isAllowed(address account, bytes32 action) external view returns (bool) {
        return _isAllowed(account, action, address(0), false);
    }

    /// @notice Same as isAllowed, but token-specific rules for `token` are applied first.
    function isAllowedToken(address account, bytes32 action, address token) external view returns (bool) {
        return _isAllowed(account, action, token, true);
    }

    /// @notice Whether a connection is allowed and, if not, why (DENY_* reason).
    /// @dev creator: CREATE_CONNECTION rule for `token` + connection limits of each of its types.
    ///      userB: must have a payout target (redirectTarget != 0), then JOIN_FULLY_PAID when
    ///      percentA == 100, else JOIN_CONNECTION, for `token`.
    function canCreateConnection(
        address creator,
        address userB,
        address token,
        uint256 totalPlan,
        uint256 percentA,
        uint256 lockDays
    ) public view returns (bool allowed, uint8 reason) {
        if (!_isAllowed(creator, ATMActions.CREATE_CONNECTION, token, true)) return (false, DENY_CREATOR);
        reason = _checkLimits(creator, token, totalPlan, percentA, lockDays);
        if (reason != CONN_OK) return (false, reason);
        if (userB != address(0)) {
            // userB must be payable somewhere (same as the Trader's setUserB check): blacklisted,
            // frozen without a usable safe wallet, or protected with a restricted safe wallet -> no
            if (redirectTarget(userB) == address(0)) return (false, DENY_USER_B);
            bytes32 action = percentA == 100 ? ATMActions.JOIN_FULLY_PAID : ATMActions.JOIN_CONNECTION;
            if (!_isAllowed(userB, action, token, true)) return (false, DENY_USER_B);
        }
        return (true, CONN_OK);
    }

    /// @notice Called by the Factory on createLink (it finds the ACL through File.accessControl()).
    ///         Same answer as canCreateConnection; anyone may call it.
    function checkConnection(
        address creator,
        address userB,
        address token,
        uint256 totalPlan,
        uint256 percentA,
        uint256 lockDays
    ) external view returns (bool allowed, uint8 reason) {
        return canCreateConnection(creator, userB, token, totalPlan, percentA, lockDays);
    }

    /// @notice Built-ins: 1 = blacklisted, 2 = frozen (incl. through the safe wallet). Others: held and not expired.
    function hasType(address account, uint256 typeId) public view returns (bool) {
        if (typeId == TYPE_BLACKLISTED) return _blacklisted[account];
        if (typeId == TYPE_FROZEN) return isFrozen(account);
        return _validType(account, typeId);
    }

    /// @notice Types that apply to the wallet now, incl. 1 (blacklisted) and 2 (frozen, also
    ///         through the safe wallet). Expired custom types are left out.
    function typesOf(address account) external view returns (uint256[] memory) {
        return _activeTypes(account);
    }

    /// @notice name is empty for built-ins 1-3 (BLACKLISTED, FROZEN, PROTECTED); id 4 is retired.
    function typeInfo(uint256 typeId)
        external
        view
        returns (string memory name, bool exists, bool disabled, bool defaultBlocked, bool daoAllowed)
    {
        TypeInfo storage t = _types[typeId];
        return (t.name, _typeExists(typeId), t.disabled, t.defaultBlocked, t.daoAllowed);
    }

    /// @notice Stored rule (0 not set, 1 allow, 2 block); tokenSpecific reads the rule for `token`.
    function typeRule(uint256 typeId, bytes32 action, address token, bool tokenSpecific) external view returns (uint8) {
        return tokenSpecific ? _tokenRules[typeId][action][token] : _rules[typeId][action];
    }

    function connectionLimitsOf(uint256 typeId, address token, bool tokenSpecific)
        external
        view
        returns (ConnectionLimits memory)
    {
        return tokenSpecific ? _tokenLimits[typeId][token] : _limits[typeId];
    }

    function isProtected(address account) public view returns (bool) {
        return _userTypeIndex[account][TYPE_PROTECTED] != 0;
    }

    // ---------------------------------------------------------------------
    // ACL DAO wiring
    // ---------------------------------------------------------------------

    /// @notice Owner should be a timelock / multisig: the ACL DAO can move safe wallets.
    function setDao(address _dao) external onlyOwner {
        dao = _dao;
        emit DaoSet(_dao);
    }

    /// @notice Any operator (or the owner) can pause the DAO hooks; only the owner unpauses.
    function pauseDao() external {
        if (!operators[msg.sender] && msg.sender != owner()) revert NotOperator();
        daoPaused = true;
        emit DaoPausedSet(true, msg.sender);
    }

    function unpauseDao() external onlyOwner {
        daoPaused = false;
        emit DaoPausedSet(false, msg.sender);
    }

    /// @notice Frozen wallet becomes PROTECTED (unfrozen, keeps its safe wallet).
    function daoGrantProtection(address wallet) external onlyDao {
        if (!_frozen[wallet] || _blacklisted[wallet]) revert NotFrozen();
        address safe = _safeWallet[wallet];
        // wallet must not be a safe wallet itself; its safe wallet must be usable and not protected
        if (_activeSafeWalletCount[wallet] != 0 || safe == address(0) || _safeUnusable(safe) || isProtected(safe)) {
            revert SafeWalletUnusable();
        }
        _frozen[wallet] = false;
        emit UnFrozen(wallet);
        _syncTypes(wallet);
        _addType(wallet, TYPE_PROTECTED);
        emit ProtectionGranted(wallet, safe);
    }

    /// @notice Sets a new safe wallet for a PROTECTED wallet.
    /// @notice New safe wallet for a PROTECTED wallet, or for a FROZEN (not blacklisted) one (move-up).
    function daoSetSafeWallet(address wallet, address newSafeWallet) external onlyDao {
        if (!isProtected(wallet) && !(_frozen[wallet] && !_blacklisted[wallet])) revert NotProtected();
        if (
            newSafeWallet == address(0) || newSafeWallet == wallet || newSafeWallet == _safeWallet[wallet] ||
            isRestricted(newSafeWallet) || _safeWalletRevoked[newSafeWallet] || isProtected(newSafeWallet)
        ) revert SafeWalletUnusable();
        _assignSafeWallet(wallet, newSafeWallet);
    }

    /// @notice Adds (`add` = true) or removes `account` in a custom type the owner opened to the DAO.
    function daoSetType(address account, uint256 typeId, bool add) external onlyDao {
        if (!_isCustomType(typeId) || !_types[typeId].daoAllowed) revert NotAssignable();
        _setType(account, typeId, add, true);
    }

    // ---------------------------------------------------------------------
    // Internal
    // ---------------------------------------------------------------------

    /// @dev Called when `a` itself becomes frozen or blacklisted: it loses PROTECTED.
    ///      If `a` is someone's safe wallet, its restrict counter moves: every linked wallet now
    ///      reads as frozen and its custom types expire. O(1), no loop over dependents.
    function _onRestricted(address a) internal {
        bool wasProtected = _removeType(a, TYPE_PROTECTED);
        if (wasProtected && _blacklisted[a]) _clearSafeWalletEntry(a);
        if (_activeSafeWalletCount[a] > 0) {
            uint256 c = ++_restrictCount[a];
            emit DependentsRestricted(a, c);
        }
    }

    /// @dev Types that apply to `account` right now: BLACKLISTED / FROZEN (incl. through the safe
    ///      wallet) and stored types that are not expired. Empty for a normal wallet (3 reads).
    function _activeTypes(address account) internal view returns (uint256[] memory out) {
        uint256[] storage list = _userTypes[account];
        uint256 n = list.length;
        bool bl = _blacklisted[account];
        bool fr = _frozen[account];
        if (!bl && !fr && n == 0) return out;
        if (!bl && !fr) fr = _inheritsFrozen(account);
        bool valid = n > 0 && _typesValid(account);
        out = new uint256[](n + 2);
        uint256 k;
        if (bl) out[k++] = TYPE_BLACKLISTED;
        if (fr) out[k++] = TYPE_FROZEN;
        for (uint256 i = 0; i < n; i++) {
            uint256 t = list[i];
            if (t == TYPE_PROTECTED || valid) out[k++] = t;
        }
        assembly {
            mstore(out, k)
        }
    }

    function _isAllowed(address account, bytes32 action, address token, bool hasToken)
        internal
        view
        returns (bool)
    {
        uint256[] memory types = _activeTypes(account);
        for (uint256 i = 0; i < types.length; i++) {
            if (_blocks(types[i], action, token, hasToken)) return false;
        }
        return true;
    }

    function _blocks(uint256 typeId, bytes32 action, address token, bool hasToken) internal view returns (bool) {
        TypeInfo storage t = _types[typeId];
        if (t.disabled) return false;
        if (hasToken) {
            uint8 tr = _tokenRules[typeId][action][token];
            if (tr != RULE_UNSET) return tr == RULE_BLOCK;
        }
        uint8 r = _rules[typeId][action];
        if (r != RULE_UNSET) return r == RULE_BLOCK;
        return t.defaultBlocked;
    }

    function _checkLimits(address creator, address token, uint256 totalPlan, uint256 percentA, uint256 lockDays)
        internal
        view
        returns (uint8 r)
    {
        uint256[] memory types = _activeTypes(creator);
        for (uint256 i = 0; i < types.length; i++) {
            r = _limitsFail(types[i], token, totalPlan, percentA, lockDays);
            if (r != CONN_OK) return r;
        }
    }

    function _limitsFail(uint256 typeId, address token, uint256 totalPlan, uint256 percentA, uint256 lockDays)
        internal
        view
        returns (uint8)
    {
        if (_types[typeId].disabled) return CONN_OK;
        ConnectionLimits storage l = _tokenLimits[typeId][token];
        if (!l.set) l = _limits[typeId];
        if (!l.set) return CONN_OK;
        if (l.minLockDays != 0 && lockDays < l.minLockDays) return DENY_LOCK_DAYS;
        if (l.maxLockDays != 0 && lockDays > l.maxLockDays) return DENY_LOCK_DAYS;
        if (l.minAmount != 0 && totalPlan < l.minAmount) return DENY_AMOUNT;
        if (l.maxAmount != 0 && totalPlan > l.maxAmount) return DENY_AMOUNT;
        if (l.minPercentA != 0 && percentA < l.minPercentA) return DENY_PERCENT;
        if (l.maxPercentA != 0 && percentA > l.maxPercentA) return DENY_PERCENT;
        if (l.startTime != 0 && block.timestamp < l.startTime) return DENY_TIME;
        if (l.endTime != 0 && block.timestamp > l.endTime) return DENY_TIME;
        return CONN_OK;
    }

    function _checkedLimits(ConnectionLimits calldata l) internal pure returns (ConnectionLimits memory out) {
        out = l;
        if (!(l.maxLockDays == 0 || l.minLockDays <= l.maxLockDays)) revert BadLimits();
        if (!(l.maxAmount == 0 || l.minAmount <= l.maxAmount)) revert BadLimits();
        if (!(l.minPercentA <= 100 && l.maxPercentA <= 100)) revert BadLimits();
        if (!(l.maxPercentA == 0 || l.minPercentA <= l.maxPercentA)) revert BadLimits();
        if (!(l.endTime == 0 || l.startTime < l.endTime)) revert BadLimits();
        out.set =
            l.minLockDays != 0 || l.maxLockDays != 0 || l.minAmount != 0 || l.maxAmount != 0 ||
            l.minPercentA != 0 || l.maxPercentA != 0 || l.startTime != 0 || l.endTime != 0;
    }

    /// @dev PROTECTED and its safe wallet is frozen / blacklisted / revoked. One level only:
    ///      the no-chains invariant guarantees the safe wallet is never PROTECTED itself.
    function _inheritsFrozen(address a) internal view returns (bool) {
        if (!isProtected(a)) return false;
        address safe = _safeWallet[a];
        return safe != address(0) && _safeUnusable(safe);
    }

    function _safeUnusable(address safe) internal view returns (bool) {
        return _blacklisted[safe] || _frozen[safe] || _safeWalletRevoked[safe];
    }

    /// @dev Custom types are valid while the safe wallet was not restricted since grant.
    function _typesValid(address a) internal view returns (bool) {
        return _typesEpoch[a] == _restrictCount[_safeWallet[a]];
    }

    function _validType(address a, uint256 typeId) internal view returns (bool) {
        if (_userTypeIndex[a][typeId] == 0) return false;
        return typeId == TYPE_PROTECTED || _typesValid(a);
    }

    /// @dev Deletes expired types (all but PROTECTED) and re-stamps the epoch. Loops over the
    ///      wallet's own list only (max MAX_TYPES_PER_USER).
    function _syncTypes(address a) internal {
        uint256 current = _restrictCount[_safeWallet[a]];
        if (_typesEpoch[a] == current) return;
        uint256[] storage list = _userTypes[a];
        for (uint256 i = list.length; i > 0; i--) {
            uint256 t = list[i - 1];
            if (t != TYPE_PROTECTED) _removeType(a, t);
        }
        _typesEpoch[a] = current;
    }

    function _notExecuted(uint256 proposalId) internal view returns (Proposal storage p) {
        require(proposalId < proposalCount, "ATMAccessControl: proposal not found");
        p = proposals[proposalId];
        require(!p.executed, "ATMAccessControl: already executed");
    }

    /// @dev batch size + no zero address
    function _checkAddrs(address[] calldata addrs) internal pure {
        _checkBatch(addrs.length);
        for (uint256 i = 0; i < addrs.length; i++) _nonZero(addrs[i]);
    }

    function _nonZero(address a) internal pure {
        require(a != address(0), "ATMAccessControl: zero address");
    }

    function _checkBatch(uint256 len) internal pure {
        require(len > 0, "ATMAccessControl: empty batch");
        require(len <= MAX_BATCH_SIZE, "ATMAccessControl: batch too large");
    }

    function _addType(address a, uint256 typeId) internal {
        if (_userTypeIndex[a][typeId] != 0) return;
        if (_userTypes[a].length >= MAX_TYPES_PER_USER) revert TooManyTypes();
        _userTypes[a].push(typeId);
        _userTypeIndex[a][typeId] = _userTypes[a].length;
        emit TypeAssigned(a, typeId);
    }

    function _removeType(address a, uint256 typeId) internal returns (bool) {
        uint256 idx = _userTypeIndex[a][typeId];
        if (idx == 0) return false;
        uint256[] storage list = _userTypes[a];
        uint256 last = list[list.length - 1];
        list[idx - 1] = last;
        _userTypeIndex[a][last] = idx;
        list.pop();
        delete _userTypeIndex[a][typeId];
        emit TypeRemoved(a, typeId);
        return true;
    }

    function _requireType(uint256 typeId) internal view {
        if (!_typeExists(typeId)) revert UnknownType();
    }

    function _typeExists(uint256 typeId) internal view returns (bool) {
        return (typeId >= TYPE_BLACKLISTED && typeId <= TYPE_PROTECTED) || _types[typeId].exists;
    }

    function _isAssignable(uint256 typeId) internal view returns (bool) {
        return typeId == TYPE_PROTECTED || _isCustomType(typeId);
    }

    /// @dev Not empty, not a built-in name, not used by another type. Returns its key.
    function _checkName(string calldata name) internal view returns (bytes32 key) {
        if (bytes(name).length == 0) revert EmptyName();
        key = keccak256(bytes(name));
        if (
            key == keccak256("BLACKLISTED") || key == keccak256("FROZEN") || key == keccak256("PROTECTED")
        ) revert ReservedName();
        if (typeIdByName[key] != 0) revert TypeExists();
    }

    function _isCustomType(uint256 typeId) internal view returns (bool) {
        return typeId >= FIRST_CUSTOM_TYPE && _types[typeId].exists;
    }

    /// @dev Returns false when nothing changed (already in that state, or
    ///      full and `strict` is false); full with `strict` reverts TooManyTypes.
    function _setType(address a, uint256 typeId, bool add, bool strict) internal returns (bool) {
        _syncTypes(a);
        if (!add) return _removeType(a, typeId);
        if (_userTypeIndex[a][typeId] != 0) return false;
        if (!strict && _userTypes[a].length >= MAX_TYPES_PER_USER) return false;
        _addType(a, typeId);
        return true;
    }

    function version() external pure returns (string memory) {
        return "v1.1.0";
    }
}

