// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title ATMActions
/// @notice Action ids checked against ATMAccessControl type rules. Every contract that asks the
///         ACL about an action uses these constants, so the ids are defined once.
/// @dev An action id is keccak256 of its name. Adding a new action = add a constant here and a
///      check in the contract that performs it; rules per type are then set in the ACL.
library ATMActions {
    /// @dev Creator side of Factory.createLink.
    bytes32 internal constant CREATE_CONNECTION = keccak256("CREATE_CONNECTION");
    /// @dev userB side of a connection where userB has to pay a share (percentA < 100).
    bytes32 internal constant JOIN_CONNECTION = keccak256("JOIN_CONNECTION");
    /// @dev userB side of a connection fully paid by the creator (percentA == 100).
    bytes32 internal constant JOIN_FULLY_PAID = keccak256("JOIN_FULLY_PAID");
}
